WITH sales_item AS (SELECT cs_item_sk, cs_call_center_sk, cs_warehouse_sk, SUM(cs_ext_sales_price) AS total_sales_amount, SUM(cs_quantity) AS total_sales_qty FROM catalog_sales GROUP BY cs_item_sk, cs_call_center_sk, cs_warehouse_sk), returns_item AS (SELECT cr_item_sk, cr_call_center_sk, cr_warehouse_sk, SUM(cr_return_amount) AS total_return_amount, SUM(cr_return_quantity) AS total_return_qty FROM catalog_returns GROUP BY cr_item_sk, cr_call_center_sk, cr_warehouse_sk), combined_item AS (SELECT s.cs_item_sk AS item_sk, s.cs_call_center_sk AS call_center_sk, s.cs_warehouse_sk AS warehouse_sk, s.total_sales_amount, s.total_sales_qty, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_return_qty, 0) AS total_return_qty, s.total_sales_amount - COALESCE(r.total_return_amount, 0) AS net_revenue FROM sales_item s LEFT JOIN returns_item r ON s.cs_item_sk = r.cr_item_sk AND s.cs_call_center_sk = r.cr_call_center_sk AND s.cs_warehouse_sk = r.cr_warehouse_sk) SELECT i.item_sk, cc.cc_call_center_id, cc.cc_name AS call_center_name, w.w_warehouse_id, w.w_warehouse_name, i.total_sales_qty, i.total_return_qty, i.total_sales_amount, i.total_return_amount, i.net_revenue, CASE WHEN i.net_revenue > 500000 THEN 'Platinum' WHEN i.net_revenue > 200000 THEN 'Gold' WHEN i.net_revenue > 50000 THEN 'Silver' ELSE 'Bronze' END AS revenue_band, PERCENT_RANK() OVER (ORDER BY i.net_revenue DESC) AS revenue_percentile_rank, ROW_NUMBER() OVER (PARTITION BY i.item_sk ORDER BY i.net_revenue DESC) AS rn_per_item FROM combined_item i JOIN call_center cc ON i.call_center_sk = cc.cc_call_center_sk JOIN warehouse w ON i.warehouse_sk = w.w_warehouse_sk WHERE i.total_sales_qty > 0 ORDER BY i.net_revenue DESC LIMIT 100
